#include "gveh.h"

void gveh_debug_print(FILE *f, const struct gveh_vehicle_s *v, gveh_i32 tick)
{
    fprintf(f, "%ld,%s,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%d,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%ld,%d,%d,%d,%d,%d,%d,%d,%ld,%d,%d,%d,%ld,%ld,%ld,%ld,%ld,%d,%d,%d,%d,%d,%ld,%ld,%ld,%d,%d,%d,%d\n",
        (long)tick,
        v->profile.name,
        (long)gveh_fx_to_int(v->body.pos.x),
        (long)gveh_fx_to_int(v->body.pos.y),
        (long)gveh_fx_to_int(v->body.pos.z),
        (long)gveh_fx_to_int(v->body.vel.x),
        (long)gveh_fx_to_int(v->body.vel.y),
        (long)gveh_fx_to_int(v->body.vel.z),
        (long)v->body.yaw,
        (long)v->grounded_count,
        (int)v->fxq.count,
        (long)v->kudos.score,
        (long)v->kudos.combo,
        (long)gveh_fx_to_int(v->nitro.charge),
        (long)gveh_fx_to_int(v->riskboost.boost),
        (long)v->takedown.takedowns,
        (long)gveh_fx_to_int(v->skill.driver),
        (long)gveh_fx_to_int(v->crashbreaker.charge),
        (long)gveh_fx_to_int(v->airframe.airspeed),
        (long)gveh_fx_to_int(v->airframe.lift),
        (long)gveh_fx_to_int(v->rotorcraft.rotor_rpm),
        (long)gveh_fx_to_int(v->rotorcraft.lift),
        (long)gveh_fx_to_int(v->airgame.fuel),
        (int)v->airgame.cannon,
        (int)v->airgame.missiles,
        (int)v->airgame.locked,
        (int)v->airgame.cargo_count,
        (int)v->avionics.locked,
        (int)v->avionics.threat_warn,
        (int)v->air_damage.engine_dead,
        (long)gveh_fx_to_int(v->air_damage.control_loss),
        (int)v->air_mission.score,
        (int)v->air_mission.medal,
        (int)v->wingman.squad_score,
        (long)gveh_fx_to_int(v->spacecraft.shield),
        (long)gveh_fx_to_int(v->spacecraft.laser),
        (long)gveh_fx_to_int(v->spacecraft.heat),
        (long)gveh_fx_to_int(v->tank4.tracks.left_power),
        (long)gveh_fx_to_int(v->tank4.tracks.right_power),
        (int)v->tank4.turret.yaw,
        (int)v->tank4.turret.elev,
        (int)v->tank4.gun.selected,
        (int)v->tank4.last_fired,
        (int)v->tank4.last_penetrated,
        (long)gveh_fx_to_int(v->tank4.last_hit.effective),
        (long)gveh_fx_to_int(v->tank4.last_hit.spall),
        (long)gveh_fx_to_int(v->tank4.crew.shock),
        (int)v->tank4.crew.alive_count,
        (int)v->tank4.modules.last_module,
        (int)v->tank4.platoon.order,
        (int)v->tank4.platoon.platoon_score);
}
